// === Tab: mySketch ===
class light{
  let pos = new PVector(0, 0, 0);
  let vel = new PVector(0, 0, 0);
  let acc = new PVector(0, 0, 0);
  r = 2;
  constructor(pos, vel){
    this.pos = pos;
    this.vel = vel;
  }
  function run(){
    if(pos.x < 0) vel.x = -vel.x;
    if(pos.x > width) vel.x = -vel.x;
    if(pos.y < 0) vel.y = -vel.y;
    if(pos.y > height) vel.y = -vel.y;
    vel.add(acc);
    pos.add(vel);
    noStroke();
    ellipse(pos.x, pos.y, r, r);
  }
}

light lights[][] = new Array(60)[600]; 
let n =0;
let c;
let time = 1;
function setup() {
  createCanvas(600, 600);
  colorMode(HSB);
  background(0);
  frameRate(60);
  let vel0 = 4;
  for (i=0; i<60; i++) {
    var vel = new PVector();
    let theta = i * 2*PI/60;
    vel.x = vel0 * cos(theta);
    vel.y = vel0 * sin(theta);
    for (j=0; j<600; j++) {
      lights[i][j] = new light(new PVector(width/2, height/2), vel);
    }
  }
}
function draw() {
  fill(0, 0, 0, 20);
  rect(0, 0, width, height);
  n = 50 + time % 200;
  let o = int(time)%300;
  if (c >= 255)  c=0;  
  else  c++;
  fill(c, 200, 255);
  for (i=0; i<60; i+=1) {
    for (j=0+o; j<n+o; j++) {
      lights[i][j].run();
    }
  }
  time++;
}

